//@ run-pass
//@ expect-stdout: CDQBIG OK
// FRONTIER (Paper 1 open item) — the exact Cayley-Dickson product over UNBOUNDED ℚ, ALL 16 components.
//
// The i64 version (sedenion_cd_full16_q.sio) does the full 16-comp ℚ product via the common-denominator
// reduction, but caps at coefficients ~1e8 (i64 output). This closes the unbounded case with a minimal,
// self-contained SIGNED BigInt (base 1e9 limbs) — so numerators/denominators are ARBITRARY precision.
//
// WHY A LOCAL BigInt. The stdlib `math::bignat` full big×big `big_mul` SIGSEGVs under souc v0.80.0
// (a single `big_mul(a,b)`, no arrays, no loop — a clean #651/#637 struct-copy repro), and `[BigInt;16]`
// SIGSEGVs (the array-of-structs wall). This brick CIRCUMVENTS both — it does NOT fix #651 — exactly as
// the i64 common-denom circumvented #637: (i) a minimal in-file BigInt built only from primitives that
// empirically compile (schoolbook big×big = big_mul_small + limb-shift + big_add-in-loop, which the spike
// confirms runs); (ii) the 16 numerators are held in FLAT scalar arrays [i64;N], never [BigInt;16].
//
// Common-denom identity: a rational sedenion = 16 integer numerators A[16] over a common denom Ad;
//   (A·B)[k] = (Σ_{i⊕j=k} σ(i,j) A[i] B[j]) / (Ad·Bd)  — an INTEGER 16-comp product of numerators.
// Certified on two cases: (1) a known zero divisor scaled by 10^40 — product EXACTLY 0 in all 16 comps
// at magnitude 10^80 (i64 would overflow into garbage; exactness holds); (2) a general 16-comp product
// with unbounded rational coefficients (components up to ~10^70). Each component's residue mod 1e9+7 is
// emitted (byte-identical across souc builds; a per-limb decimal printer is miscompiled differently by
// bin/souc vs stage2) and cross-verified vs the Python oracle; the EXACT decimals are witnessed by Lean
// (native Int, SounioCDqbig.lean) and the oracle (exact ℚ). Case 1's annihilation is checked structurally.

struct SBig { limb: [i64; 12], len: i64, neg: i64 }

fn cd_sigma_c(a: i64, b: i64, bits: i64) -> i64 with Mut, Panic, Div {
    if a == 0 || b == 0 { return 1 }
    if bits <= 1 { return 0 - 1 }
    let half = 1 << (bits - 1)
    let a_hi = if a >= half { 1 } else { 0 }
    let b_hi = if b >= half { 1 } else { 0 }
    let a_lo = a & (half - 1)
    let b_lo = b & (half - 1)
    if a_hi == 0 && b_hi == 0 { return cd_sigma_c(a_lo, b_lo, bits - 1) }
    if a_hi == 0 && b_hi == 1 { return cd_sigma_c(b_lo, a_lo, bits - 1) }
    if a_hi == 1 && b_hi == 0 {
        if b_lo == 0 { return cd_sigma_c(a_lo, 0, bits - 1) }
        return 0 - cd_sigma_c(a_lo, b_lo, bits - 1)
    }
    if b_lo == 0 { return 0 - cd_sigma_c(0, a_lo, bits - 1) }
    cd_sigma_c(b_lo, a_lo, bits - 1)
}
fn s_is_zero(a: SBig) -> bool with Mut, Panic { a.len == 1 && a.limb[0 as usize] == 0 }
fn sfrom(x: i64) -> SBig with Mut, Panic, Div {
    var r = SBig { limb: [0; 12], len: 1, neg: if x < 0 { 1 } else { 0 } }
    var v = if x < 0 { 0 - x } else { x }
    var i = 0
    while v > 0 && i < 12 {
        r.limb[i as usize] = v % 1000000000
        v = v / 1000000000
        i = i + 1
    }
    if i > 0 { r.len = i }
    r
}
// magnitude * small (m >= 0), sign dropped
fn smul_small(a: SBig, m: i64) -> SBig with Mut, Panic, Div {
    var r = SBig { limb: [0; 12], len: a.len, neg: 0 }
    var carry = 0
    var i = 0
    while i < a.len {
        let p = a.limb[i as usize] * m + carry
        r.limb[i as usize] = p % 1000000000
        carry = p / 1000000000
        i = i + 1
    }
    while carry > 0 && i < 12 {
        r.limb[i as usize] = carry % 1000000000
        carry = carry / 1000000000
        r.len = i + 1
        i = i + 1
    }
    r
}
fn sshift(a: SBig, sh: i64) -> SBig with Mut, Panic, Div {
    if s_is_zero(a) { return a }
    var r = SBig { limb: [0; 12], len: a.len + sh, neg: 0 }
    var i = a.len - 1
    while i >= 0 {
        if (i + sh) < 12 { r.limb[(i + sh) as usize] = a.limb[i as usize] }
        i = i - 1
    }
    r
}
fn spow10(n: i64) -> SBig with Mut, Panic, Div {
    var r = sfrom(1)
    var c = 0
    while c < n { r = smul_small(r, 10)  c = c + 1 }
    r
}
// magnitude compare: 1 if |a|>|b|, -1 if <, 0 eq
fn ucmp(a: SBig, b: SBig) -> i64 with Mut, Panic, Div {
    var i = 11
    while i >= 0 {
        let av = a.limb[i as usize]
        let bv = b.limb[i as usize]
        if av > bv { return 1 }
        if av < bv { return 0 - 1 }
        i = i - 1
    }
    0
}
// magnitude add
fn uadd(a: SBig, b: SBig) -> SBig with Mut, Panic, Div {
    var r = SBig { limb: [0; 12], len: if a.len > b.len { a.len } else { b.len }, neg: 0 }
    var carry = 0
    var i = 0
    while i < r.len {
        let s = a.limb[i as usize] + b.limb[i as usize] + carry
        r.limb[i as usize] = s % 1000000000
        carry = s / 1000000000
        i = i + 1
    }
    if carry > 0 && r.len < 12 { r.limb[r.len as usize] = carry  r.len = r.len + 1 }
    r
}
// magnitude sub, requires |a| >= |b|
fn usub(a: SBig, b: SBig) -> SBig with Mut, Panic, Div {
    var r = SBig { limb: [0; 12], len: a.len, neg: 0 }
    var borrow = 0
    var i = 0
    while i < a.len {
        var d = a.limb[i as usize] - b.limb[i as usize] - borrow
        if d < 0 { d = d + 1000000000  borrow = 1 } else { borrow = 0 }
        r.limb[i as usize] = d
        i = i + 1
    }
    // trim len
    var L = a.len
    while L > 1 && r.limb[(L - 1) as usize] == 0 { L = L - 1 }
    r.len = L
    r
}
fn sadd(a: SBig, b: SBig) -> SBig with Mut, Panic, Div {
    if a.neg == b.neg {
        var r = uadd(a, b)
        if !s_is_zero(r) { r.neg = a.neg }
        return r
    }
    let c = ucmp(a, b)
    if c == 0 { return sfrom(0) }
    if c > 0 {
        var r = usub(a, b)
        if !s_is_zero(r) { r.neg = a.neg }
        return r
    }
    var r = usub(b, a)
    if !s_is_zero(r) { r.neg = b.neg }
    r
}
fn smul(a: SBig, b: SBig) -> SBig with Mut, Panic, Div {
    var acc = sfrom(0)
    var i = 0
    while i < b.len {
        let part = sshift(smul_small(a, b.limb[i as usize]), i)
        acc = uadd(acc, part)
        i = i + 1
    }
    if !s_is_zero(acc) {
        acc.neg = if a.neg == b.neg { 0 } else { 1 }
    }
    acc
}
fn sneg(a: SBig) -> SBig with Mut, Panic, Div {
    var r = SBig { limb: [0; 12], len: a.len, neg: 0 }
    var t = 0
    while t < 12 { r.limb[t as usize] = a.limb[t as usize]  t = t + 1 }
    if !s_is_zero(a) { r.neg = 1 - a.neg }
    r
}
// Signed residue of a BigInt modulo a small prime p, normalized to [0, p). We emit residues (not the
// full decimal) because printing 70-digit numbers via a per-limb helper is miscompiled DIFFERENTLY by
// the two souc builds (bin/souc vs stage2 diverge on print-in-loop / print_int newline), whereas
// `print("RES ") print_int(x) print("\n")` is byte-identical on both. A digit error changes the residue
// with overwhelming probability; the EXACT decimal values are witnessed independently by Lean (native
// Int) and the Python oracle (exact ℚ). Horner fold: r = (r*base + limb) mod p, high limb to low.
fn smod_small(a: SBig, p: i64) -> i64 with Mut, Panic, Div {
    var r = 0
    var i = 11
    while i >= 0 {
        r = (r * 1000000000 + a.limb[i as usize]) % p
        i = i - 1
    }
    if a.neg == 1 && r != 0 { r = p - r }
    r
}

// compute (A·B)[k] for all k and print; A,B given as flat limb arrays + nz flags; dens Ad,Bd.
// returns 1 if all 16 comps are zero (annihilation), else 0.
fn cd16_emit(tag: i64, alimb: [i64; 192], alen: [i64; 16], aneg: [i64; 16], anz: [i64; 16],
             blimb: [i64; 192], blen: [i64; 16], bneg: [i64; 16], bnz: [i64; 16],
             ad: SBig, bd: SBig) -> i64 with IO, Mut, Panic, Div {
    var allzero = 1
    var k = 0
    while k < 16 {
        var acc = sfrom(0)
        var i = 0
        while i < 16 {
            let j = i ^ k
            if anz[i as usize] == 1 && bnz[j as usize] == 1 {
                // reconstruct A[i], B[j]
                var ai = SBig { limb: [0; 12], len: alen[i as usize], neg: aneg[i as usize] }
                var bj = SBig { limb: [0; 12], len: blen[j as usize], neg: bneg[j as usize] }
                var t = 0
                while t < 12 {
                    ai.limb[t as usize] = alimb[(i * 12 + t) as usize]
                    bj.limb[t as usize] = blimb[(j * 12 + t) as usize]
                    t = t + 1
                }
                var term = smul(ai, bj)
                if cd_sigma_c(i, j, 4) < 0 { term = sneg(term) }
                acc = sadd(acc, term)
            }
            i = i + 1
        }
        if !s_is_zero(acc) { allzero = 0 }
        // emit residue mod (10^9+7); order is (case1 comp0..15, den), (case2 comp0..15, den).
        print("RES ")
        print_int(smod_small(acc, 1000000007))
        print("\n")
        k = k + 1
    }
    let den = smul(ad, bd)
    print("RES ")
    print_int(smod_small(den, 1000000007))
    print("\n")
    allzero
}

fn main() with IO, Mut, Panic, Div {
    // ---- CASE 1: (e3 + e10)(e6 - e15) scaled by 10^40 -> exact annihilation, den 1 ----
    var A1l = [0; 192]
    var A1len = [1; 16]
    var A1neg = [0; 16]
    var A1nz = [0; 16]
    var B1l = [0; 192]
    var B1len = [1; 16]
    var B1neg = [0; 16]
    var B1nz = [0; 16]
    let S = spow10(40)
    // A1[3] = 10^40, A1[10] = 10^40
    var idxa = [3, 10]
    var p = 0
    while p < 2 {
        let idx = idxa[p as usize]
        var t = 0
        while t < 12 { A1l[(idx * 12 + t) as usize] = S.limb[t as usize]  t = t + 1 }
        A1len[idx as usize] = S.len
        A1nz[idx as usize] = 1
        p = p + 1
    }
    // B1[6] = 10^40, B1[15] = -10^40
    var idxb = [6, 15]
    var sgnb = [0, 1]
    p = 0
    while p < 2 {
        let idx = idxb[p as usize]
        var t = 0
        while t < 12 { B1l[(idx * 12 + t) as usize] = S.limb[t as usize]  t = t + 1 }
        B1len[idx as usize] = S.len
        B1neg[idx as usize] = sgnb[p as usize]
        B1nz[idx as usize] = 1
        p = p + 1
    }
    let c1_zero = cd16_emit(1, A1l, A1len, A1neg, A1nz, B1l, B1len, B1neg, B1nz, sfrom(1), sfrom(1))

    // ---- CASE 2: general 16-comp product, unbounded rational coeffs ----
    // A2: idx {1,2,4,8,15} = {1e30, 3e28, -5e35, 1e33, 7e20} / 6
    // B2: idx {1,5,7,10}   = {2e31, -1e29, 4e27, 9e34} / 10
    var A2l = [0; 192]
    var A2len = [1; 16]
    var A2neg = [0; 16]
    var A2nz = [0; 16]
    var B2l = [0; 192]
    var B2len = [1; 16]
    var B2neg = [0; 16]
    var B2nz = [0; 16]
    var pa = [1, 2, 4, 8, 15]
    var pae = [30, 28, 35, 33, 20]
    var pam = [1, 3, 5, 1, 7]
    var pan = [0, 0, 1, 0, 0]
    p = 0
    while p < 5 {
        let idx = pa[p as usize]
        var v = smul_small(spow10(pae[p as usize]), pam[p as usize])
        var t = 0
        while t < 12 { A2l[(idx * 12 + t) as usize] = v.limb[t as usize]  t = t + 1 }
        A2len[idx as usize] = v.len
        A2neg[idx as usize] = pan[p as usize]
        A2nz[idx as usize] = 1
        p = p + 1
    }
    var pb = [1, 5, 7, 10]
    var pbe = [31, 29, 27, 34]
    var pbm = [2, 1, 4, 9]
    var pbn = [0, 1, 0, 0]
    p = 0
    while p < 4 {
        let idx = pb[p as usize]
        var v = smul_small(spow10(pbe[p as usize]), pbm[p as usize])
        var t = 0
        while t < 12 { B2l[(idx * 12 + t) as usize] = v.limb[t as usize]  t = t + 1 }
        B2len[idx as usize] = v.len
        B2neg[idx as usize] = pbn[p as usize]
        B2nz[idx as usize] = 1
        p = p + 1
    }
    let c2_zero = cd16_emit(2, A2l, A2len, A2neg, A2nz, B2l, B2len, B2neg, B2nz, sfrom(6), sfrom(10))

    print("ANNIHILATION_C1 ")
    print_int(c1_zero)
    print("\n")
    // Case 1 annihilates exactly at 10^80; Case 2 general product emitted (cross-checked vs oracle).
    if c1_zero == 1 && c2_zero == 0 {
        println("CDQBIG OK")
    } else {
        println("CDQBIG FAIL")
    }
}

//@ run-pass
//@ requires: madaros
//@ exit-code: 0
//@ description: ker L_w spanned by e3+e10, e2−e11, e4−e13, e5+e12
// Full Test Suite CI uses souc-stage2 (lean_single). Madaros runs this graph.

use algebra::sedenion::{sed_norm_sq, sed_basis}
use algebra::sedenion_action::{sed_canonical_zd_pair}
use algebra::sedenion_kernel::{
    sed_ker_lw_gen, sed_ker_lw_span_rank, sed_lmul_vec_nsq,
}

fn abs_f(x: f64) -> f64 {
    if x < 0.0 { 0.0 - x } else { x }
}

fn main() -> i64 with IO, Mut, Div, Panic {
    var z: [f64; 16] = [0.0; 16]
    var w: [f64; 16] = [0.0; 16]
    sed_canonical_zd_pair(&!z, &!w)
    var e1: [f64; 16] = [0.0; 16]
    sed_basis(1, &!e1)

    var ok: i64 = 1
    var k: i64 = 0
    while k < 4 {
        var h: [f64; 16] = [0.0; 16]
        sed_ker_lw_gen(k, &!h)
        if abs_f(sed_norm_sq(&h) - 2.0) > 1.0e-9 { ok = 0 }
        if sed_lmul_vec_nsq(&w, &h) > 1.0e-9 { ok = 0 }
        if abs_f(sed_lmul_vec_nsq(&e1, &h) - 2.0) > 1.0e-9 { ok = 0 }
        if sed_lmul_vec_nsq(&z, &h) <= 1.0e-9 { ok = 0 }
        if k == 0 {
            var dz = 0.0
            var t: i64 = 0
            while t < 16 {
                let x = h[t] - z[t]
                dz = dz + x * x
                t = t + 1
            }
            if dz > 1.0e-9 { ok = 0 }
        }
        k = k + 1
    }
    if sed_ker_lw_span_rank() != 4 { ok = 0 }

    if ok == 1 { 0 } else { 1 }
}

//@ run-pass
// tests/run-pass/sedenion_ratbig_channel_case1.sio
//
// Split-out single-case variant. souc v0.80.0 hits TWO distinct codegen
// flakes on the combined 3-case file, both empirically bisected here:
//  (a) whole-program struct-heavy function-count capacity wall (same
//      family as stdlib/math/bignat.sio's note) -- the combined file
//      (~28 fns) SIGSEGVs; trimmed to <=24 functions per file below.
//  (b) a SEPARATE, sharper bug: calling unat_is_zero(...) in `main` on a
//      BigNat pulled (directly or via a wrapper fn) out of the `.num.mag`
//      of a Rat that was itself produced by rat_add/rat_mul/rat_reduce
//      SIGSEGVs codegen every time -- even at a function count that
//      otherwise compiles fine, even wrapped in its own helper fn, even
//      as unreferenced-looking dead code. Calling unat_print (or
//      big_print) on the SAME value at the SAME call site is fine; only
//      unat_is_zero (or an inlined equivalent boolean field compare) on
//      that specific derivation chain crashes. Root cause not
//      determined (register/stack-slot corruption is suspected given the
//      deep gcd/divmod call tree inside rat_reduce, but not confirmed).
//      WORKAROUND: do not call any is-zero check on a rat_add/rat_mul
//      result inside the .sio at all -- print the reduced (num, den)
//      pair (rat_print) and decide zero-ness FROM THE PRINTED OUTPUT
//      (canonical reduced form means num=0,den=1 iff the value is
//      exactly zero). That is exactly the "decidable rational equality"
//      the task asks for, so no functionality is lost.
//  (c) a THIRD, real correctness bug (not just a crash): souc's by-value
//      struct-copy semantics are violated by the "var r = a; r.neg =
//      !a.neg; ...; r" pattern this file's big_neg originally used
//      (copied verbatim from stdlib/math/bignat.sio) -- mutating r.neg
//      ALSO mutated the caller's original argument in place (reproduced
//      on a bare BigInt local, not just a struct field: `let neg = big_
//      neg(n)` silently flips the sign of `n` itself too). Confirmed via
//      scripts/research/ratbig_oracle.py cross-check: case 2 printed a
//      nonzero r5/r12 before this fix, which is mathematically wrong
//      (t*s + t*(-s) must be exactly 0) -- the bug corrupted `s` in
//      place when computing delta = -s, so later reuses of `s` picked up
//      the flipped sign. FIXED by rewriting big_neg to build a fresh
//      a fresh BigInt struct literal (mag unchanged, neg flipped) instead of
//      copy-then-mutate; this stdlib/math/bignat.sio big_neg pattern
//      should be treated as suspect anywhere it is reused. Do NOT trust
//      "compiles and runs and prints a plausible-looking number" here --
//      every printed value in this file is oracle cross-checked.
//
// Case 1: locus point (1,1,1,-1) -> r5=r12=0 exactly
// Cross-checked against scripts/research/ratbig_oracle.py (Python
// fractions.Fraction) -- see sedenion_ratbig_channel.sio for the full
// commented spec (channel definition, all 3 cases, the general design).

struct BigNat { limb: [i64; 64], len: i64 }
struct BigInt { mag: BigNat, neg: bool }
struct UnatDivRes { q: BigNat, r: BigNat }
struct BigDivRes { q: BigInt, r: BigInt }
struct Rat { num: BigInt, den: BigInt }

fn unat_from_i64(x: i64) -> BigNat with Mut, Panic, Div {
    var b = BigNat { limb: [0; 64], len: 1 }
    var v = x
    var i = 0
    while v > 0 && i < 64 {
        b.limb[i as usize] = v - (v / 1000000000) * 1000000000
        v = v / 1000000000
        i = i + 1
    }
    if i == 0 { i = 1 }
    b.len = i
    b
}

fn unat_is_zero(a: BigNat) -> bool with Mut, Panic {
    a.len == 1 && a.limb[0] == 0
}

fn unat_cmp(a: BigNat, b: BigNat) -> i64 with Mut, Panic {
    var result = 0
    if a.len > b.len { result = 1 }
    if a.len < b.len { result = 0 - 1 }
    if a.len == b.len {
        var i = a.len - 1
        var done = false
        while i >= 0 && !done {
            if a.limb[i as usize] > b.limb[i as usize] { result = 1; done = true }
            if a.limb[i as usize] < b.limb[i as usize] { result = 0 - 1; done = true }
            i = i - 1
        }
    }
    result
}

fn unat_add(a: BigNat, b: BigNat) -> BigNat with Mut, Panic, Div {
    var r = BigNat { limb: [0; 64], len: 0 }
    var carry = 0
    var i = 0
    var n = a.len
    if b.len > n { n = b.len }
    while i < n {
        var av = 0
        var bv = 0
        if i < a.len { av = a.limb[i as usize] }
        if i < b.len { bv = b.limb[i as usize] }
        let s = av + bv + carry
        r.limb[i as usize] = s - (s / 1000000000) * 1000000000
        carry = s / 1000000000
        i = i + 1
    }
    if carry > 0 { r.limb[i as usize] = carry; i = i + 1 }
    r.len = i
    r
}

fn unat_sub(a: BigNat, b: BigNat) -> BigNat with Mut, Panic, Div {
    var r = BigNat { limb: [0; 64], len: 0 }
    var borrow = 0
    var i = 0
    while i < a.len {
        var bv = 0
        if i < b.len { bv = b.limb[i as usize] }
        var d = a.limb[i as usize] - bv - borrow
        borrow = 0
        if d < 0 { d = d + 1000000000; borrow = 1 }
        r.limb[i as usize] = d
        i = i + 1
    }
    var l = a.len
    while l > 1 && r.limb[(l - 1) as usize] == 0 { l = l - 1 }
    r.len = l
    r
}

fn unat_mul(a: BigNat, b: BigNat) -> BigNat with Mut, Panic, Div {
    var r = BigNat { limb: [0; 64], len: 1 }
    var i = 0
    while i < a.len {
        var carry = 0
        var j = 0
        while j < b.len {
            let idx = i + j
            let prod = a.limb[i as usize] * b.limb[j as usize] + r.limb[idx as usize] + carry
            r.limb[idx as usize] = prod - (prod / 1000000000) * 1000000000
            carry = prod / 1000000000
            j = j + 1
        }
        var k = i + b.len
        while carry > 0 {
            let s = r.limb[k as usize] + carry
            r.limb[k as usize] = s - (s / 1000000000) * 1000000000
            carry = s / 1000000000
            k = k + 1
        }
        i = i + 1
    }
    var l = a.len + b.len
    if l > 64 { l = 64 }
    while l > 1 && r.limb[(l - 1) as usize] == 0 { l = l - 1 }
    r.len = l
    r
}

fn unat_divmod(a: BigNat, b: BigNat) -> UnatDivRes with Mut, Panic, Div {
    var q = BigNat { limb: [0; 64], len: a.len }
    var rem = BigNat { limb: [0; 64], len: 1 }
    var i = a.len - 1
    while i >= 0 {
        var shifted = BigNat { limb: [0; 64], len: 0 }
        var isz = unat_is_zero(rem)
        if isz { shifted.limb[0] = a.limb[i as usize]; shifted.len = 1 }
        if !isz {
            shifted.limb[0] = a.limb[i as usize]
            var si = 0
            while si < rem.len { shifted.limb[(si + 1) as usize] = rem.limb[si as usize]; si = si + 1 }
            shifted.len = rem.len + 1
        }
        rem = shifted
        var lo = 0
        var hi = 999999999
        while lo < hi {
            let mid = lo + (hi - lo + 1) / 2
            let trial = unat_mul_small_local(b, mid)
            if unat_cmp(trial, rem) <= 0 { lo = mid }
            if unat_cmp(trial, rem) > 0 { hi = mid - 1 }
        }
        q.limb[i as usize] = lo
        rem = unat_sub(rem, unat_mul_small_local(b, lo))
        i = i - 1
    }
    var l = q.len
    while l > 1 && q.limb[(l - 1) as usize] == 0 { l = l - 1 }
    q.len = l
    UnatDivRes { q: q, r: rem }
}

fn unat_mul_small_local(a: BigNat, m: i64) -> BigNat with Mut, Panic, Div {
    var b = BigNat { limb: [0; 64], len: a.len }
    var carry = 0
    var i = 0
    while i < a.len {
        let prod = a.limb[i as usize] * m + carry
        b.limb[i as usize] = prod - (prod / 1000000000) * 1000000000
        carry = prod / 1000000000
        i = i + 1
    }
    while carry > 0 && i < 64 {
        b.limb[i as usize] = carry - (carry / 1000000000) * 1000000000
        carry = carry / 1000000000
        i = i + 1
    }
    b.len = i
    b
}

fn unat_gcd(a: BigNat, b: BigNat) -> BigNat with Mut, Panic, Div {
    var x = a
    var y = b
    while !unat_is_zero(y) {
        let dr = unat_divmod(x, y)
        let nx = y
        let ny = dr.r
        x = nx
        y = ny
    }
    x
}

fn unat_print_pad9(v: i64) with IO, Mut, Panic, Div {
    var d = 100000000
    while d > 0 {
        print_int((v / d) - ((v / (d * 10)) * 10))
        d = d / 10
    }
}

fn unat_print(a: BigNat) with IO, Mut, Panic, Div {
    print_int(a.limb[(a.len - 1) as usize])
    var i = a.len - 2
    while i >= 0 { unat_print_pad9(a.limb[i as usize]); i = i - 1 }
}

fn big_from_i64(x: i64) -> BigInt with Mut, Panic, Div {
    var neg = false
    var v = x
    if v < 0 { neg = true; v = 0 - v }
    BigInt { mag: unat_from_i64(v), neg: neg }
}



fn big_neg(a: BigInt) -> BigInt with Mut, Panic {
    var newneg = !a.neg
    if unat_is_zero(a.mag) { newneg = false }
    BigInt { mag: a.mag, neg: newneg }
}

fn big_add(a: BigInt, b: BigInt) -> BigInt with Mut, Panic, Div {
    var r = BigInt { mag: a.mag, neg: false }
    if a.neg == b.neg {
        r.mag = unat_add(a.mag, b.mag)
        r.neg = a.neg
    }
    if a.neg != b.neg {
        let c = unat_cmp(a.mag, b.mag)
        if c == 0 { r.mag = unat_from_i64(0); r.neg = false }
        if c > 0 { r.mag = unat_sub(a.mag, b.mag); r.neg = a.neg }
        if c < 0 { r.mag = unat_sub(b.mag, a.mag); r.neg = b.neg }
    }
    if unat_is_zero(r.mag) { r.neg = false }
    r
}

fn big_mul(a: BigInt, b: BigInt) -> BigInt with Mut, Panic, Div {
    var r = BigInt { mag: unat_mul(a.mag, b.mag), neg: (a.neg != b.neg) }
    if unat_is_zero(r.mag) { r.neg = false }
    r
}

fn big_divmod(a: BigInt, b: BigInt) -> BigDivRes with Mut, Panic, Div {
    let dr = unat_divmod(a.mag, b.mag)
    var q = BigInt { mag: dr.q, neg: (a.neg != b.neg) }
    var r = BigInt { mag: dr.r, neg: a.neg }
    if unat_is_zero(q.mag) { q.neg = false }
    if unat_is_zero(r.mag) { r.neg = false }
    BigDivRes { q: q, r: r }
}

fn big_gcd(a: BigInt, b: BigInt) -> BigInt with Mut, Panic, Div {
    BigInt { mag: unat_gcd(a.mag, b.mag), neg: false }
}

fn big_print(a: BigInt) with IO, Mut, Panic, Div {
    if a.neg { print("-") }
    unat_print(a.mag)
}


// -- Exact rational layer: Rat { num: BigInt, den: BigInt }, den always > 0,
// reduced so gcd(|num|, den) == 1. --

fn rat_reduce(n_in: BigInt, d_in: BigInt) -> Rat with Mut, Panic, Div {
    var n = n_in
    var d = d_in
    if d.neg { n = big_neg(n); d = big_neg(d) }
    var result = Rat { num: big_from_i64(0), den: big_from_i64(1) }
    if unat_is_zero(n.mag) {
        result = Rat { num: big_from_i64(0), den: big_from_i64(1) }
    }
    if !unat_is_zero(n.mag) {
        let g = big_gcd(n, d)
        let qn = big_divmod(n, g)
        let qd = big_divmod(d, g)
        result = Rat { num: qn.q, den: qd.q }
    }
    result
}

fn rat_make(n: i64, d: i64) -> Rat with Mut, Panic, Div {
    rat_reduce(big_from_i64(n), big_from_i64(d))
}

fn rat_add(x: Rat, y: Rat) -> Rat with Mut, Panic, Div {
    let n = big_add(big_mul(x.num, y.den), big_mul(y.num, x.den))
    let d = big_mul(x.den, y.den)
    rat_reduce(n, d)
}

fn rat_mul(x: Rat, y: Rat) -> Rat with Mut, Panic, Div {
    let n = big_mul(x.num, y.num)
    let d = big_mul(x.den, y.den)
    rat_reduce(n, d)
}

fn rat_print(x: Rat) with IO, Mut, Panic, Div {
    big_print(x.num)
    print(" ")
    big_print(x.den)
    print("\n")
}

fn main() with IO, Mut, Panic, Div {
    let alpha = rat_make(1, 1)
